# Check the exact structure of what defines a "complete" T-junction
# A T-junction exists when BOTH horizontal AND vertical lines pass through the point

def has_horizontal_line_at(r, c):
    """Check if a horizontal line spans across column c at row r"""
    # Look left from c until we hit something non-3 (like 5 or 4)
    look_left = True
    for col in range(c-1, max(-1, c-11), -1):
        if input_grid[r][col] == 9:
            continue
        elif input_grid[r][col] == 3:
            look_left = False
            break
        else:
            # Found 5 or 4
            look_left = False
            break

    # Look right from c until we hit something non-3
    look_right = True
    for col in range(c+1, min(26, c+11)):
        if input_grid[r][col] == 9:
            continue
        elif input_grid[r][col] == 3:
            look_right = False
            break
        else:
            # Found 5 or 4  
            look_right = False
            break

    return look_left and look_right

def has_vertical_line_at(r, c):
    """Check if a vertical line spans across row r at column c"""
    # Look up from r
    look_up = True
    for row in range(r-1, max(-1, r-7), -1):
        if input_grid[row][c] == 9:
            continue
        elif input_grid[row][c] == 3:
            look_up = False
            break
        else:
            look_up = False
            break

    # Look down from r
    look_down = True
    for row in range(r+1, min(30, r+7)):
        if input_grid[row][c] == 9:
            continue
        elif input_grid[row][c] == 3:
            look_down = False
            break
        else:
            look_down = False
            break

    return look_up and look_down

print("\nLine completeness check per corner:")
for coord in sorted(corner_to_regions.keys()):
    r, c = coord
    h_line = has_horizontal_line_at(r, c)
    v_line = has_vertical_line_at(r, c)
    val = input_grid[r][c]

    is_marked = val != 3
    expected_marked = h_line and v_line

    print(f"{coord}: H={h_line}, V={v_line}, marked={is_marked}, expected={expected_marked}, match={is_marked==expected_marked}")

# Correct understanding: 3s = border/lines, 9s = filled regions, 4/5 = special markers on intersections
def has_horizontal_line_at(r, c):
    """Check if row r has a continuous line (of 3s) through column c"""
    # Check left of c - should be 3 until we hit a marker or end of line
    look_left = True
    for col in range(c-1, max(-1, c-11), -1):
        val = input_grid[r][col]
        if val == 9:
            # Shouldn't happen if r is a separator row
            look_left = False
            break
        elif val == 3:
            continue
        else:
            # Found a marker (4 or 5) - that's part of the line
            continue

    # Check right of c
    look_right = True  
    for col in range(c+1, min(26, c+11)):
        val = input_grid[r][col]
        if val == 9:
            look_right = False
            break
        elif val == 3:
            continue
        else:
            continue

    return look_left and look_right

def has_vertical_line_at(r, c):
    """Check if column c has a continuous line (of 3s) through row r"""
    # Check up from r
    look_up = True
    for row in range(r-1, max(-1, r-7), -1):
        val = input_grid[row][c]
        if val == 9:
            look_up = False
            break
        elif val == 3:
            continue
        else:
            continue

    # Check down from r
    look_down = True
    for row in range(r+1, min(30, r+7)):
        val = input_grid[row][c]
        if val == 9:
            look_down = False
            break
        elif val == 3:
            continue
        else:
            continue

    return look_up and look_down

print("\nLine completeness check:")
for coord in sorted(corner_to_regions.keys()):
    r, c = coord
    h_line = has_horizontal_line_at(r, c)
    v_line = has_vertical_line_at(r, c)
    val = input_grid[r][c]

    is_marked = val != 3

    print(f"{coord}: H={h_line}, V={v_line}, marked={is_marked}")

# Try another hypothesis: mark corners based on whether they touch more regions
corner_region_counts = {}
for coord, regs in corner_to_regions.items():
    count = len(regs)
    if coord not in corner_region_counts:
        corner_region_counts[coord] = []
    corner_region_counts[coord].append(count)

print("Corner region counts:")
