# Get current intersection values from input grid
current_intersections = {}
for r, c in [(0,0), (0,11), (0,22), (7,0), (7,11), (7,22),
             (14,0), (14,11), (14,22), (21,0), (21,11), (21,22),
             (29,0), (29,11), (29,22)]:
    current_intersections[(r,c)] = input_grid[r][c]

print("Current intersection values:")
for k, v in sorted(current_intersections.items()):
    print(f"  {k}: {v}")

# Now let's count how many regions touch each corner
def get_region_at_intersection(intersection):
    """Return list of region dicts that contain this corner"""
    r_start, r_end = intersection[0], intersection[0] + 1
    c_start, c_end = intersection[1], intersection[1] + 1

    touching = []
    for reg in regions:
        # Region spans rows [reg['top_left'][0]+1 : reg['bottom_left'][0]] 
        # and cols [reg['top_left'][1]+1 : reg['top_right'][1]]
        if reg['top_left'][0] <= r_start < reg['bottom_left'][0]:
            if reg['top_left'][1] <= c_start < reg['top_right'][1]:
                touching.append(reg['id'])
    return touching

print("\nRegions touching each intersection:")
corner_to_regions_v2 = {}
for r, c in current_intersections.keys():
    regs = get_region_at_intersection((r, c))
    corner_to_regions_v2[(r,c)] = regs
    print(f"  ({r},{c}): regions {regs}, value={input_grid[r][c]}")

# Count how many regions are to the LEFT, RIGHT, TOP, BOTTOM of each corner
def get_adjacent_region_ids(r, c):
    """Find regions adjacent to this corner position"""
    adj = []
    # Look left/right (same row as corner)
    for reg in regions:
        if reg['top_left'][0] + 1 < r <= reg['bottom_left'][0]:
            # Region spans this row
            if reg['top_right'][1] == c:
                adj.append(('R', reg['id']))  # To the left
            elif reg['top_left'][1] == c:
                adj.append(('L', reg['id']))  # To the right
    # Look top/bottom (same col as corner)
    for reg in regions:
        if reg['top_left'][1] + 1 < c <= reg['top_right'][1]:
            # Region spans this col
            if reg['bottom_right'][0] == r:
                adj.append(('D', reg['id']))  # Below
            elif reg['top_left'][0] == r:
                adj.append(('U', reg['id']))  # Above
    return adj

print("Adjacent regions for each corner:")
for r, c in sorted(current_intersections.keys()):
    adj = get_adjacent_region_ids(r, c)
    print(f"({r},{c}): {adj}, value={input_grid[r][c]}")

# Let me check: which corners are "interior" (have regions on all 4 sides)?
def count_adjacent_regions(r, c):
    count = 0
    # Check left (region ends at col c)
    for reg in regions:
        if reg['top_left'][0] < r <= reg['bottom_left'][0]:
            if reg['top_right'][1] == c:
                count += 1
    # Check right (region starts at col c)
    for reg in regions:
        if reg['top_left'][0] < r <= reg['bottom_left'][0]:
            if reg['top_left'][1] == c:
                count += 1
    # Check top (region ends at row r)
    for reg in regions:
        if reg['top_left'][1] < c <= reg['top_right'][1]:
            if reg['bottom_right'][0] == r:
                count += 1
    # Check bottom (region starts at row r)
    for reg in regions:
        if reg['top_left'][1] < c <= reg['top_right'][1]:
            if reg['top_left'][0] == r:
                count += 1
    return count

print("Adjacent region counts:")
for r, c in sorted(current_intersections.keys()):
    cnt = count_adjacent_regions(r, c)
    print(f"({r},{c}): {cnt} adj regions, current={input_grid[r][c]}")

# Categorize by quadrant/band
separator_rows = [0, 7, 14, 21, 29]
for r, c in sorted(current_intersections.keys()):
    # Find band index (0=above row 0, 1=rows 0-6, etc.)
    band = 0
    for i, sep_r in enumerate(separator_rows):
        if r >= sep_r:
            band = i
            break
    else:
        band = len(separator_rows)  # Below all separators

    print(f"Band {band}: ({r},{c}), value={input_grid[r][c]}")
